INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('45e61254-2e01-4151-90c7-354d4cd3d321', '49233c34-14ff-50c0-a604-61cf65e881c9', 'nl', 'Vario 2BR', 'Vario 2BR is een mobiel huis uit de lijn Premium Vario: 13,84 × 8,44 m, bebouwde oppervlakte 116,81 m², voor 4-6 personen. 18 cm PUR-isolatie, zadeldak 13°, wandhoogte 250 cm, vloerverwarming standaard.', '2026-11-04T19:23:55.185Z'::timestamptz, '2026-11-04T19:31:26.075Z'::timestamptz, '[{"id":"vario-2br-room-0","name":"Woonkamer met keuken"},{"id":"vario-2br-room-1","name":"Keuken met eethoek"},{"id":"vario-2br-room-2","name":"Slaapkamer"},{"id":"vario-2br-room-3","name":"Kamer"},{"id":"vario-2br-room-4","name":"Badkamer"},{"id":"vario-2br-room-5","name":"Badkamer 2"},{"id":"vario-2br-room-6","name":"Kleedkamer"},{"id":"vario-2br-room-7","name":"Entree"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Staalconstructie met PUR-isolatie, op een onderstel van het type FF (vlak).', 'Zadeldak, 13°', 'Keuze uit betaalde opties uit de prijslijst van de producent (onderstel, isolatie, installaties, uitrusting) en een interieurstijl. Een eigen ontwerp is als aparte optie mogelijk.', NULL) ON CONFLICT DO NOTHING;
